let adminData;const views={overview:['Owner dashboard','A live view of the people, companies, and work moving through Trades.'],companies:['Users & companies','Every company account and owner currently on Trades.'],jobs:['Marketplace jobs','All posted work, bidding activity, and project status.'],activity:['Recent activity','A privacy-conscious operational feed of platform events.']};const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'})[char]);const date=value=>value?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date(value)):'-';const relative=value=>{const days=Math.floor((Date.now()-new Date(value))/864e5);return days<1?'Today':days===1?'Yesterday':`${days} days ago`};const initials=value=>String(value||'Trades Owner').split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();async function request(path){const response=await fetch(path),data=await response.json();if(!response.ok){const error=new Error(data.error||'Unable to load owner console.');error.status=response.status;throw error}return data}
function switchView(name){document.querySelectorAll('[data-admin-view]').forEach(button=>button.classList.toggle('active',button.dataset.adminView===name));document.querySelectorAll('.admin-view').forEach(view=>view.hidden=view.id!==`${name}View`);document.getElementById('pageTitle').textContent=views[name][0];document.getElementById('pageDescription').textContent=views[name][1];history.replaceState({},'',name==='overview'?'/admin':`/admin#${name}`)}
function rankMarkup(items){const max=items[0]?.count||1;return items.slice(0,7).map(item=>`<div class="rank-row"><section><strong>${esc(item.label)}</strong><div><span style="width:${Math.max(5,item.count/max*100)}%"></span></div></section><b>${item.count}</b></div>`).join('')||'<div class="empty-admin">No data yet.</div>'}
function renderOverview(){const m=adminData.metrics,stats=[['Companies',m.companies,'total marketplace businesses'],['Users',m.users,`${adminData.system.activeSessions} active sessions`],['Contractor only',m.contractorOnlyCompanies??m.contractors,'hire subcontractors'],['Subcontractor only',m.subcontractorOnlyCompanies??m.subcontractors,'find trade work'],['Dual accounts',m.dualRoleCompanies??0,'hire and bid'],['Open jobs',m.publishedJobs,'currently accepting bids'],['Bids',m.bids,'submitted across all jobs']];document.getElementById('metricGrid').innerHTML=stats.map(([label,value,note])=>`<article class="admin-stat"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`).join('');document.getElementById('pulseGrid').innerHTML=[['Published',m.publishedJobs,'open jobs'],['Awarded',m.awardedJobs,'scheduled work'],['Completed',m.completedJobs,'finished jobs'],['Messages',m.messages,'sent total'],['Portfolio',m.portfolioProjects,'project showcases']].map(([label,value,note])=>`<div><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('');document.getElementById('locationBreakdown').innerHTML=rankMarkup(adminData.breakdowns.locations);document.getElementById('tradeBreakdown').innerHTML=rankMarkup(adminData.breakdowns.trades);document.getElementById('companyPreview').innerHTML=adminData.companies.slice(0,6).map(company=>`<article class="preview-company"><strong>${esc(company.name)}</strong><span>${esc([company.city,company.state].filter(Boolean).join(', ')||'Location not set')}</span><small>${esc(company.owner?.email||'No owner record')} · ${relative(company.createdAt)}</small></article>`).join('')||'<div class="empty-admin">No companies have joined yet.</div>'}
function companyRows(companies){return companies.map(company=>`<tr><td><strong>${esc(company.name)}</strong><small>${esc([company.city,company.state].filter(Boolean).join(', ')||'Location not set')} · ${company.profileCompletion}% profile</small></td><td><strong>${esc(company.owner?.fullName||'Unknown')}</strong><small>${esc(company.owner?.email||'No email')} ${company.owner?.activeSession?'· Active now':''}</small></td><td><strong>${esc(company.capabilities.join(' & '))}</strong><small>${esc(company.trades.join(', ')||'No trades selected')}</small></td><td><strong>${company.postedJobs} jobs · ${company.bidsSubmitted} bids</strong><small>${company.connections} trusted connections</small></td><td><strong>${company.rating?`${company.rating} stars`:'No rating yet'}</strong><small>${company.credentials} credentials · ${company.portfolioProjects} projects</small></td><td><strong>${date(company.createdAt)}</strong></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-admin">No matching companies.</div></td></tr>'}
function jobRows(jobs){return jobs.map(job=>`<tr><td><strong>${esc(job.title)}</strong><small>${esc(job.trade)}</small></td><td><strong>${esc(job.postingCompany?.name||'Unknown')}</strong><small>${job.awardedCompany?`Awarded to ${esc(job.awardedCompany.name)}`:'Not awarded'}</small></td><td><strong>${esc([job.city,job.state].filter(Boolean).join(', '))}</strong><small>${esc(job.budget||'Budget not listed')}</small></td><td><span class="status-pill ${esc(job.status)}">${esc(job.status)}</span></td><td><strong>${job.bidCount}</strong></td><td><strong>${date(job.createdAt)}</strong></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-admin">No matching jobs.</div></td></tr>'}
function renderActivity(){const type=document.getElementById('activityFilter').value,items=adminData.activity.filter(item=>!type||item.type===type);document.getElementById('activityList').innerHTML=items.map(item=>`<div class="activity-row"><span class="activity-icon">${esc(item.type.slice(0,2))}</span><div><strong>${esc(item.title)}</strong><small>${esc(item.detail)}</small></div><time>${relative(item.createdAt)}</time></div>`).join('')||'<div class="empty-admin">No activity in this category yet.</div>'}
function render(){document.getElementById('ownerInitials').textContent=initials(adminData.owner.fullName);document.getElementById('ownerName').textContent=adminData.owner.fullName;document.getElementById('ownerEmail').textContent=adminData.owner.email;document.getElementById('systemMeta').textContent=`${adminData.system.storageProvider} · ${adminData.system.activeSessions} active sessions`;renderOverview();document.getElementById('companyTable').innerHTML=companyRows(adminData.companies);document.getElementById('jobTable').innerHTML=jobRows(adminData.jobs);renderActivity()}
document.querySelectorAll('[data-admin-view]').forEach(button=>button.onclick=()=>switchView(button.dataset.adminView));document.querySelectorAll('[data-go-view]').forEach(button=>button.onclick=()=>switchView(button.dataset.goView));document.getElementById('companySearch').oninput=event=>{const q=event.target.value.toLowerCase();document.getElementById('companyTable').innerHTML=companyRows(adminData.companies.filter(company=>JSON.stringify(company).toLowerCase().includes(q)))};document.getElementById('jobSearch').oninput=event=>{const q=event.target.value.toLowerCase();document.getElementById('jobTable').innerHTML=jobRows(adminData.jobs.filter(job=>JSON.stringify(job).toLowerCase().includes(q)))};document.getElementById('activityFilter').onchange=renderActivity;document.getElementById('adminSignOut').onclick=async()=>{await fetch('/api/admin/logout',{method:'POST'});location.href='/admin/login'};
request('/api/admin').then(data=>{adminData=data;render();switchView(location.hash.slice(1)in views?location.hash.slice(1):'overview')}).catch(error=>{const alert=document.getElementById('adminAlert');alert.hidden=false;alert.textContent=error.status===401?'Opening secure admin sign in...':error.message;document.querySelectorAll('.admin-view').forEach(view=>view.hidden=true);if(error.status===401)setTimeout(()=>location.href='/admin/login',600)});

companyRows=companies=>companies.map(company=>`<tr><td><strong>${esc(company.name)}</strong><small>${esc([company.city,company.state].filter(Boolean).join(', ')||'Location not set')} &middot; ${company.profileCompletion}% profile</small></td><td><strong>${esc(company.owner?.fullName||'Unknown')}</strong><small>${esc(company.owner?.email||'No email')} ${company.owner?.activeSession?'&middot; Active now':''}</small></td><td><strong>${esc(company.capabilities.join(' & '))}</strong><small>${esc(company.trades.join(', ')||'No trades selected')}</small></td><td><strong>${company.postedJobs} jobs &middot; ${company.bidsSubmitted} bids</strong><small>${company.connections} trusted connections</small></td><td><strong>${company.rating?`${company.rating} stars`:'No rating yet'}</strong><small>${company.credentials} credentials &middot; ${company.portfolioProjects} projects</small></td><td><strong>${date(company.createdAt)}</strong></td><td><span class="status-pill ${company.accountStatus==='suspended'?'suspended':''}">${esc(company.accountStatus||'active')}</span><button class="button ${company.accountStatus==='suspended'?'button-outline':'button-dark'} admin-account-action" type="button" data-company-status="${esc(company.id)}" data-next-status="${company.accountStatus==='suspended'?'active':'suspended'}">${company.accountStatus==='suspended'?'Reactivate':'Suspend'}</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty-admin">No matching companies.</div></td></tr>';
document.getElementById('companyTable').onclick=async event=>{const button=event.target.closest('[data-company-status]');if(!button)return;button.disabled=true;try{const response=await fetch(`/api/admin/companies/${button.dataset.companyStatus}/status`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:button.dataset.nextStatus})}),result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to update account status.');Object.assign(adminData.companies.find(company=>company.id===result.company.id),result.company);render()}catch(error){const alert=document.getElementById('adminAlert');alert.hidden=false;alert.textContent=error.message}finally{button.disabled=false}};
const baseAdminOverview=renderOverview;renderOverview=function(){baseAdminOverview();const root=document.getElementById('ownerActionList');if(!root)return;const suspended=adminData.companies.filter(company=>company.accountStatus==='suspended').length,noBidJobs=adminData.jobs.filter(job=>job.status==='published'&&!job.bidCount).length,incompleteProfiles=adminData.companies.filter(company=>(company.profileCompletion||0)<60).length,items=[['Open feedback',adminData.metrics.openFeedback,'Review user ideas and issues','feedback'],['Suspended accounts',suspended,'Reactivate or keep blocked','companies'],['Jobs without bids',noBidJobs,'Watch supply and demand gaps','jobs'],['Incomplete profiles',incompleteProfiles,'Companies below 60% complete','companies']];root.innerHTML=items.map(([label,value,note,view])=>`<button class="owner-action-row" type="button" data-owner-view="${view}"><span><strong>${esc(label)}</strong><small>${esc(note)}</small></span><b>${value}</b></button>`).join('');root.querySelectorAll('[data-owner-view]').forEach(button=>button.onclick=()=>switchView(button.dataset.ownerView))};
views.revenue=['Revenue dashboard','Estimated awarded value, bid volume, and market activity for future monetization.'];const money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(value)||0);function revenueRank(items){return items.map(item=>`<div class="revenue-rank-row"><span><strong>${esc(item.label)}</strong><small>${item.awardedJobs} awarded jobs &middot; ${item.bidCount} bids</small></span><b>${money(item.awardedValue)}</b></div>`).join('')||'<div class="empty-admin">No awarded work yet.</div>'}function renderRevenue(){const root=document.getElementById('revenueMetricGrid');if(!root||!adminData?.revenue)return;const r=adminData.revenue,m=r.metrics;root.innerHTML=[['Awarded value',money(m.awardedValue),'estimated accepted work'],['5% fee potential',money(m.estimatedPlatformFeeAt5),'if Trades charged a fee'],['Bid pipeline',money(m.bidPipelineValue),'all active submitted bids'],['Avg bid value',money(m.averageBidValue),'across active bids'],['Avg bids / open job',m.averageBidsPerOpenJob,'marketplace liquidity'],['Awarded jobs',m.awardedJobs,'jobs won on platform']].map(([label,value,note])=>`<article class="admin-stat"><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`).join('');document.getElementById('revenueMarketList').innerHTML=revenueRank(r.markets);document.getElementById('revenueTradeList').innerHTML=revenueRank(r.trades);document.getElementById('revenueAwardsList').innerHTML=r.recentAwards.map(item=>`<article class="revenue-award"><span class="trade-pill">${esc(item.trade)}</span><div><strong>${esc(item.title)}</strong><small>${esc(item.contractor)} awarded ${esc(item.subcontractor)} &middot; ${esc(item.market)} &middot; ${date(item.awardedAt)}</small></div><b>${money(item.value)}</b></article>`).join('')||'<div class="empty-admin">Awarded jobs will appear here once bids are accepted.</div>'}const baseRevenueRender=render;render=function(){baseRevenueRender();renderRevenue()};
